/* Bounded nonlinear point/segment constraints; analytic curves retain their control data. */
const StudioSketch=(()=>{
 const num=n=>typeof n==='number'&&Number.isFinite(n)&&Math.abs(n)<=5000;
 const exact=(v,k)=>v&&typeof v==='object'&&Object.keys(v).sort().join(',')===[...k].sort().join(',');
 const pair=['horizontal','vertical','length','coincident','angle'],four=['equalLength','parallel','perpendicular'];
 function valid(cs,n){return Array.isArray(cs)&&cs.length<=32&&cs.every(c=>{if(!c||!Number.isInteger(c.a)||c.a<0||c.a>=n)return false;if(c.type==='fixed')return exact(c,['a','type','value'])&&Array.isArray(c.value)&&c.value.length===2&&c.value.every(num);const indices=four.includes(c.type)?['a','b','c','d']:['a','b'];if(!pair.includes(c.type)&&!four.includes(c.type)||!exact(c,[...indices,'type','value'])||!indices.every(k=>Number.isInteger(c[k])&&c[k]>=0&&c[k]<n)||c.a===c.b||four.includes(c.type)&&c.c===c.d||!num(c.value))return false;return c.type==='length'?c.value>=.1:c.type==='angle'?Math.abs(c.value)<=180:c.value===0;});}
 function equations(p,c){const a=p[c.a];if(c.type==='fixed')return a.map((v,k)=>v-c.value[k]);const b=p[c.b],dx=b[0]-a[0],dy=b[1]-a[1],len=Math.hypot(dx,dy);if(c.type==='horizontal')return [dy];if(c.type==='vertical')return [dx];if(c.type==='length')return [len-c.value];if(c.type==='coincident')return [dx,dy];if(len<1e-8)throw Error('A constrained segment has zero length.');if(c.type==='angle'){let delta=Math.atan2(dy,dx)-c.value*Math.PI/180;delta=Math.atan2(Math.sin(delta),Math.cos(delta));return [delta*len];}const q=p[c.c],r=p[c.d],ux=r[0]-q[0],uy=r[1]-q[1],len2=Math.hypot(ux,uy);if(len2<1e-8)throw Error('A constrained segment has zero length.');return [c.type==='equalLength'?len-len2:c.type==='parallel'?(dx*uy-dy*ux)/Math.max(len,len2):(dx*ux+dy*uy)/Math.max(len,len2)];}
 function residual(p,c){return Math.hypot(...equations(p,c));}
 function matrixSolve(a,b){const n=b.length,m=a.map((r,i)=>[...r,b[i]]);for(let k=0;k<n;k++){let pivot=k;for(let j=k+1;j<n;j++)if(Math.abs(m[j][k])>Math.abs(m[pivot][k]))pivot=j;[m[k],m[pivot]]=[m[pivot],m[k]];if(Math.abs(m[k][k])<1e-20)throw Error('Constraint system is singular.');const d=m[k][k];for(let j=k;j<=n;j++)m[k][j]/=d;for(let i=0;i<n;i++)if(i!==k){const v=m[i][k];for(let j=k;j<=n;j++)m[i][j]-=v*m[k][j];}}return m.map(r=>r[n]);}
 const rows=(p,cs)=>cs.flatMap(c=>equations(p,c));
 function jacobian(p,cs,r){return r.map(()=>Array(p.length*2).fill(0)).map((row,i)=>row);}
 function derivative(p,cs,r){const j=jacobian(p,cs,r);for(let k=0;k<p.length*2;k++){const q=p.map(v=>[...v]),h=1e-5;q[k>>1][k%2]+=h;const next=rows(q,cs);for(let i=0;i<r.length;i++)j[i][k]=(next[i]-r[i])/h;}return j;}
 function solve(outline,constraints){if(!valid(constraints,outline.length))throw Error('Invalid sketch constraints.');let p=outline.map(v=>[...v]),lambda=1e-5;for(let step=0;step<120;step++){const r=rows(p,constraints),cost=r.reduce((n,v)=>n+v*v,0);if(Math.sqrt(cost)<1e-5)return p;const j=derivative(p,constraints,r),a=j.map((row,i)=>j.map((other,k)=>row.reduce((n,v,t)=>n+v*other[t],0)+(i===k?lambda:0))),weights=matrixSolve(a,r),delta=Array(p.length*2).fill(0).map((_,k)=>j.reduce((n,row,i)=>n+row[k]*weights[i],0)),q=p.map((v,i)=>v.map((x,k)=>x-delta[i*2+k]));if(q.some(v=>v.some(x=>!num(x)))){lambda*=10;continue;}const next=rows(q,constraints).reduce((n,v)=>n+v*v,0);if(next<cost){p=q;lambda=Math.max(1e-10,lambda/3);}else lambda=Math.min(1e12,lambda*10);}
 throw Error('Constraints conflict or did not converge. Remove a constraint or adjust its value; the saved solid is unchanged.');}
 function diagnostics(points,cs){if(!valid(cs,points.length))throw Error('Invalid sketch constraints.');const r=rows(points,cs),j=derivative(points,cs,r).map(v=>[...v]);let rank=0;for(let col=0;col<points.length*2&&rank<j.length;col++){let k=rank;for(let i=rank+1;i<j.length;i++)if(Math.abs(j[i][col])>Math.abs(j[k][col]))k=i;if(Math.abs(j[k][col])<1e-5)continue;[j[k],j[rank]]=[j[rank],j[k]];const d=j[rank][col];for(let c=col;c<points.length*2;c++)j[rank][c]/=d;for(let i=rank+1;i<j.length;i++){const v=j[i][col];for(let c=col;c<points.length*2;c++)j[i][c]-=v*j[rank][c];}rank++;}return {degreesOfFreedom:points.length*2-rank,redundantEquations:r.length-rank,maxResidual:r.length?Math.max(...r.map(Math.abs)):0};}
 function validCurves(curves,n){return Array.isArray(curves)&&curves.length<=8&&new Set(curves.map(c=>c?.edge)).size===curves.length&&curves.every(c=>exact(c,['edge','type','control','segments'])&&Number.isInteger(c.edge)&&c.edge>=0&&c.edge<n&&['quadratic','arc'].includes(c.type)&&Array.isArray(c.control)&&c.control.length===2&&c.control.every(num)&&Number.isInteger(c.segments)&&c.segments>=2&&c.segments<=16)&&n+curves.reduce((s,c)=>s+c.segments-1,0)<=128;}
 function sample(points,curves=[]){if(!validCurves(curves,points.length))throw Error('Invalid analytic curves. Use up to eight and 128 tessellated vertices.');const out=[];for(let edge=0;edge<points.length;edge++){const a=points[edge],b=points[(edge+1)%points.length],c=curves.find(c=>c.edge===edge);out.push([...a]);if(!c)continue;let centre,start,span,radius;if(c.type==='arc'){const m=c.control,d=2*(a[0]*(m[1]-b[1])+m[0]*(b[1]-a[1])+b[0]*(a[1]-m[1]));if(Math.abs(d)<1e-8)throw Error('An arc requires three non-collinear points.');const aa=a[0]**2+a[1]**2,mm=m[0]**2+m[1]**2,bb=b[0]**2+b[1]**2;centre=[(aa*(m[1]-b[1])+mm*(b[1]-a[1])+bb*(a[1]-m[1]))/d,(aa*(b[0]-m[0])+mm*(a[0]-b[0])+bb*(m[0]-a[0]))/d];radius=Math.hypot(a[0]-centre[0],a[1]-centre[1]);start=Math.atan2(a[1]-centre[1],a[0]-centre[0]);const norm=x=>(x+Math.PI*4)%(Math.PI*2),end=norm(Math.atan2(b[1]-centre[1],b[0]-centre[0])-start),mid=norm(Math.atan2(m[1]-centre[1],m[0]-centre[0])-start);span=mid<end?end:end-Math.PI*2;}for(let i=1;i<c.segments;i++){const t=i/c.segments;out.push(c.type==='quadratic'?[0,1].map(k=>(1-t)**2*a[k]+2*(1-t)*t*c.control[k]+t*t*b[k]):[centre[0]+radius*Math.cos(start+span*t),centre[1]+radius*Math.sin(start+span*t)]);}}return out;}
 function corners(width,height,radius,rounded=true){if(![width,height,radius].every(num)||radius<.2||width<=2*radius+.2||height<=2*radius+.2)throw Error('Corner size must fit inside the rectangle, leaving straight edges.');const x=width/2,y=height/2,r=radius,k=Math.SQRT1_2*r,outline=[[-x+r,-y],[x-r,-y],[x,-y+r],[x,y-r],[x-r,y],[-x+r,y],[-x,y-r],[-x,-y+r]],centres=[[x-r,-y+r],[x-r,y-r],[-x+r,y-r],[-x+r,-y+r]],dirs=[[k,-k],[k,k],[-k,k],[-k,-k]],curves=rounded?centres.map((c,i)=>({edge:i*2+1,type:'arc',control:c.map((v,k)=>v+dirs[i][k]),segments:8})):[];return {outline,curves};}
  function curve(points,edge,control,segments){
    if(!Number.isInteger(edge)||edge<0||edge>=points.length||!Array.isArray(control)||control.length!==2||control.some(n=>!Number.isFinite(n)||Math.abs(n)>5000)||!Number.isInteger(segments)||segments<2||segments>16||points.length+segments-1>64)throw Error('Choose an edge, a finite control point and 2–16 segments within the 64-vertex limit.');
    const a=points[edge],b=points[(edge+1)%points.length],insert=[];for(let i=1;i<segments;i++){const t=i/segments;insert.push([0,1].map(k=>(1-t)**2*a[k]+2*(1-t)*t*control[k]+t*t*b[k]));}
    return [...points.slice(0,edge+1),...insert,...points.slice(edge+1)];
  }
  return {valid,residual,solve,curve,diagnostics,validCurves,sample,corners};
})();
